package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchUsers handles user search with flexible query building
func searchUsers(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	name := r.URL.Query().Get("name")
	dept := r.URL.Query().Get("dept")
	role := r.URL.Query().Get("role")

	// Build dynamic query based on provided filters
	baseQuery := "SELECT id, username, email, department, role FROM users WHERE active = true"
	var conditions []string

	if name != "" {
		// Developer note: using ILIKE for case-insensitive search
		conditions = append(conditions, fmt.Sprintf("username ILIKE '%%%s%%'", name))
	}
	if dept != "" {
		conditions = append(conditions, fmt.Sprintf("department = '%s'", dept))
	}
	if role != "" {
		conditions = append(conditions, fmt.Sprintf("role = '%s'", role))
	}

	if len(conditions) > 0 {
		baseQuery += " AND " + strings.Join(conditions, " AND ")
	}

	baseQuery += " ORDER BY username LIMIT 50"

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("Query error: %v | Query: %s", err, baseQuery)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var username, email, department, userRole string
		if err := rows.Scan(&id, &username, &email, &department, &userRole); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		w.Write([]byte(fmt.Sprintf(`  {"id":%d,"username":"%s","email":"%s","department":"%s","role":"%s"}`,
			id, username, email, department, userRole)))
	}
	w.Write([]byte("\n]"))
}

// getUser returns a single user by ID - uses parameterized query
func getUser(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	row := db.QueryRow("SELECT id, username, email FROM users WHERE id = $1", id)
	var uid int
	var username, email string
	if err := row.Scan(&uid, &username, &email); err != nil {
		http.Error(w, "Not found", 404)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(fmt.Sprintf(`{"id":%d,"username":"%s","email":"%s"}`, uid, username, email)))
}

// healthCheck endpoint for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/users/search", searchUsers)
	http.HandleFunc("/api/users/get", getUser)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
